    float *dout_h = static_cast<float *>(std::malloc(sizeof(float) * n));
    float *dinp_h = static_cast<float *>(std::malloc(sizeof(float) * n));
    if (!inp || !dout_h || !dinp_h) {
        std::fprintf(stderr, "host malloc failed\n");
        return 2;
    }
